/**
 * 路由 meta 的类型声明。
 *
 * 不加这一段的话 `route.meta.layout` 是 `unknown`，`v-if` 里能跑但
 * 拼错了属性名不会有任何提示 —— 这类错误的表现是"守卫静默失效"，
 * 比报错难查得多。把这个项目的路由约定写下来，拼错就编译不过。
 */
import 'vue-router'

declare module 'vue-router' {
  interface RouteMeta {
    /** 页面标题。内容区自己渲染（顶栏只有搜索和动作，见 router/index.ts） */
    title?: string
    /**
     * 布局。
     *
     *   `'bare'` —— **不套应用外壳**（无侧栏、无顶栏）。
     *             目前只有登录页用：它要在没有会话的情况下也能渲染，
     *             而外壳里的侧栏/顶栏本身依赖登录态（用户名、角色菜单），
     *             套上去会先闪一下空壳。
     *   缺省     —— 走 `App.vue` 的标准外壳。
     */
    layout?: 'bare'
    /**
     * 免登录可访问。
     *
     * ⚠️ **默认是"需要登录"**：新增路由忘了标，结果是被守卫挡住（安全的一侧）；
     * 反过来默认公开的话，漏标就是漏防。
     */
    public?: boolean
    /**
     * 允许访问的角色。缺省 = 所有已登录角色都能进。
     *
     * ⚠️ 与侧栏的 `NavItem.roles` **必须一致** —— 不一致的两种表现都很难受：
     * 菜单里有但进不去（点一下就弹回来），或者进得去但菜单里没有
     * （用户以为系统坏了）。改一处必须改另一处。
     *
     * ⚠️ 这仍然是**界面层**的拦截。手改前端代码、或直接 curl 后端接口
     * 都绕得过（凡是后端确实有资源要保护的地方，判据都在后端）。
     * 本项的作用是"别让人撞进一个对他没有意义的页面"。
     */
    roles?: readonly ('admin' | 'designer' | 'user')[]
  }
}
